export async function cleanupWindowsBuildWorkspaces(directories, primaryFailure, remove = rm) {
  const results = await Promise.allSettled(directories.map(directory => Promise.resolve().then(() =>
    remove(directory, { recursive: true, force: true, maxRetries: 3, retryDelay: 20 }))));
  const failures = results.filter(result => result.status === "rejected").map(result => result.reason);
  if (failures.length) {
    const error = new AggregateError(primaryFailure === undefined ? failures : [primaryFailure, ...failures],
      "Windows native build workspace cleanup failed.", primaryFailure === undefined ? undefined : { cause: primaryFailure });
    error.code = primaryFailure?.code ?? "build_cleanup_failed";
    throw error;
  }
}

